import { requireUser } from "@/lib/guard";
import { BackButton } from "@/components/BackButton";
import { prisma } from "@/lib/prisma";
import { canManageEvents } from "@/lib/roles";
import { KanbanBoard } from "./KanbanBoard";

export default async function KanbanPage({
  searchParams,
}: {
  searchParams: Promise<{ owner?: string }>;
}) {
  const user = await requireUser();
  const { owner: ownerFilter } = await searchParams;

  const isStaff = canManageEvents(user.role);

  // Staff see all items; others see only their own.
  const whereOwner = isStaff
    ? ownerFilter && ownerFilter !== "all" ? { ownerId: ownerFilter } : {}
    : { ownerId: user.id };

  const rawItems = await prisma.actionItem.findMany({
    where: whereOwner,
    orderBy: [{ dueDate: "asc" }, { createdAt: "asc" }],
    include: {
      owner: { select: { id: true, name: true, email: true } },
      minutes: {
        select: {
          event: { select: { title: true } },
        },
      },
    },
  });

  const items = rawItems.map((i) => ({
    id: i.id,
    title: i.title,
    status: i.status as "TODO" | "IN_PROGRESS" | "DONE",
    dueDate: i.dueDate ? i.dueDate.toISOString().slice(0, 10) : null,
    eventTitle: i.minutes.event.title,
    ownerName: i.owner?.name ?? i.owner?.email ?? null,
  }));

  // For staff: load all users for the filter dropdown.
  const users = isStaff
    ? await prisma.user.findMany({
        select: { id: true, name: true, email: true },
        orderBy: [{ name: "asc" }, { email: "asc" }],
      })
    : [];

  const totals = {
    todo: items.filter((i) => i.status === "TODO").length,
    inProgress: items.filter((i) => i.status === "IN_PROGRESS").length,
    done: items.filter((i) => i.status === "DONE").length,
  };

  return (
    <div className="space-y-6">
      <BackButton href="/" label="Dashboard" />
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold text-gray-900">Action Items</h1>
          <p className="mt-0.5 text-sm text-gray-500">
            {totals.todo} to do · {totals.inProgress} in progress · {totals.done} done
          </p>
        </div>

        {isStaff && users.length > 0 && (
          <form method="GET">
            <select
              name="owner"
              defaultValue={ownerFilter ?? "all"}
              onChange={(e) => e.currentTarget.form?.submit()}
              className="rounded-md border border-gray-300 px-3 py-1.5 text-sm focus:outline-none"
            >
              <option value="all">All assignees</option>
              {users.map((u) => (
                <option key={u.id} value={u.id}>
                  {u.name ?? u.email}
                </option>
              ))}
            </select>
          </form>
        )}
      </div>

      {items.length === 0 ? (
        <div className="rounded-xl border bg-white px-8 py-16 text-center">
          <p className="text-sm text-gray-500">No action items yet.</p>
          <p className="mt-1 text-xs text-gray-400">
            Action items are created from meeting minutes.
          </p>
        </div>
      ) : (
        <KanbanBoard
          items={items}
          canMoveAny={isStaff}
          currentUserId={user.id}
          ownerFilter={ownerFilter ?? "all"}
        />
      )}
    </div>
  );
}
